"""Describe stored boundary tradeoffs and cliffs; never rerate finished results."""
import csv,gzip,io,json,statistics
from run import ROOT,R,sha,put,reg
def main():
 report=json.loads((R/'report.json').read_text());plan=json.loads((R/'plan.json').read_text());old=json.loads((ROOT/plan['anchor_source']['report']).read_text());finished_sha=sha(R/'report.json');rows=[]
 for c in report['configs'].values():
  name=f"perp_zero_pair_B{c['BTC_lookback_days']}H{int(c['BTC_return_hurdle']*100):02d}_E30H{int(c['ETH_return_hurdle']*100):02d}";a=old['configs'][name]
  rows.append({'name':c['name'],'old_ETH30_name':name,'old_status_unchanged':a['status'],'new_status':c['status'],'old_positive_folds1':a['positive_folds_1x'],'new_positive_folds1':c['positive_folds_1x'],'folds1_difference':c['positive_folds_1x']-a['positive_folds_1x'],**{f'return{k}_difference_pp':c['scenes'][k]['net_return_pct']-a['scenes'][k]['net_return_pct'] for k in ['1','2','3']},'DD3_difference_pp':c['scenes']['3']['max_drawdown_pct']-a['scenes']['3']['max_drawdown_pct']})
 b=io.StringIO(newline='');w=csv.DictWriter(b,fieldnames=list(rows[0]),lineterminator='\n');w.writeheader();w.writerows(rows);(R/'boundary_comparison.csv').write_text(b.getvalue())
 edges=list(csv.DictReader((R/'joint_edges.csv').open()));diffs=[abs(float(e['sharpe3_delta'])) for e in edges];threshold=2*statistics.stdev(diffs);cliffs=[e for e,d in zip(edges,diffs) if d>threshold];biggest=max(edges,key=lambda e:abs(float(e['return3_delta_pp'])))
 review={'report_sha256_preserved':finished_sha,'new_vs_same_BTC_and_ETH_hurdle_old30':{'comparisons':len(rows),'new_return3_lower':sum(r['return3_difference_pp']<0 for r in rows),'new_return3_higher':sum(r['return3_difference_pp']>0 for r in rows),'new_positive_folds1_increased':sum(r['folds1_difference']>0 for r in rows),'new_positive_folds1_decreased':sum(r['folds1_difference']<0 for r in rows)},'cliff_rule':'Descriptive |adjacent Sharpe3 change| > 2 * sample standard deviation of all216 absolute adjacent changes;skill diagnostic,not new selection gate.','cliff_threshold':threshold,'flagged_edges':cliffs,'flagged_edge_count':len(cliffs),'largest_abs_adjacent_return3_edge':biggest,'not_an_independent_confirmation':True,'full_grid_positive_return3_fraction':report['joint_grid_sensitivity']['positive3_fraction'],'full_grid_positive_Sharpe3_fraction':report['joint_grid_sensitivity']['positive_sharpe3_fraction'],'cliff_limit':'Four axes have unequal day steps and heterogeneous magnitudes;retain all edges,not a calibrated statistical test.','selection_limits':'No DSR/PBO computed. Reused330dayhistory and previously seen components remain development evidence.'};put(R/'sensitivity_review.json',review)
 # Reconcile persisted complete CSVs with every actual new and original readonly metric.
 cost=list(csv.DictReader((R/'sensitivity.csv').open()));folds=list(csv.DictReader((R/'fold_results.csv').open()));daily=list(csv.DictReader(io.StringIO(gzip.decompress((R/'daily_equity.csv.gz').read_bytes()).decode())));assert len(cost)==243 and len(folds)==2673 and len(daily)==53622 and len(edges)==216
 grid={**{n:c for n,c in old['configs'].items() if c['ETH_lookback_days']==30},**report['configs']}
 for row in cost:
  c=grid[row['name']];z=c['scenes'][row['cost_multiplier']];assert row['NAV_sha256_f64le']==z['NAV_sha256_f64le'] and row['read_only_anchor']==str(c['ETH_lookback_days']==30)
  for p in ['net_return_pct','max_drawdown_pct','daily_mark_drawdown_pct','sharpe_365','calmar','cost_usdt','funding_usdt']:assert float(row[p])==z[p]
 for row in folds:
  f=grid[row['name']]['scenes'][row['cost_multiplier']]['folds'][int(row['fold'])-1]
  for p in ['net_return_pct','max_drawdown_pct','sharpe_365','calmar']:assert (float(row[p])==f[p]) if f[p] is not None else row[p]==''
 for row in daily:assert float(row['equity_usdt'])==report['configs'][row['name']]['scenes'][row['cost_multiplier']]['daily_equity_usdt'][int(row['boundary_index'])]
 assert sha(R/'report.json')==finished_sha
 state=json.loads((R/'forward_state.json').read_text());records=reg.read_records(ROOT/'research/automation/registry.jsonl');qualified=[{'name':c['name'],'fingerprint':c['fingerprint'],'original_status':c['status'],'return3':c['scenes']['3']['net_return_pct'],'DD3':c['scenes']['3']['max_drawdown_pct'],'positive_folds1':c['positive_folds_1x']} for c in report['configs'].values() if c['status']=='passed']
 nxt={'report':str((R/'report.json').relative_to(ROOT)),'report_sha256':finished_sha,'new_configs_finished':54,'qualified_historical_references':qualified,'old27_anchor_qualification_unchanged':plan['anchor_source'],'raw_weights':[1,1],'total_initial_collateral_usdt':20000,'new_forward_accounts_created':0,'next_research':'Read18newqualified and36rejected results beforeproposingnewconfiguration. Allnew3xprofitsarelowerthanmatchedETH30oldparents;qualificationbreadthandnetprofitareseparate. No exact rerun. L33+requiresrealearlierhistoryandnewcausalwindowproof;do notnegative-indexfuturetail. Any newrules/weights mustprefreeze,reserve andindependentlyaudit.','source_component_reuse_policy':'18fulloldledgersand54originalNAVhashes remain inplace;newparentsreference fullcomponentstate/trade/funding reconstruction,notnewcomponentbacktests.','original_SMA_next_state':str((R/'forward_state.json').relative_to(ROOT)),'original_SMA_next_state_sha256':sha(R/'forward_state.json'),'next_daily_decision_utc':state['next_daily_decision_utc'],'original_SMA_next_mark_policy':'Continue exact original floatingquantity/cash/desired/trades/costs andfullNAVprefix from00:30. BeforeOct25UTC00:01 onlyappendclosedmarks;laterdecisionuses originalSMA65/1percent. No forcedexit before2027-03-31.','paper10_policy':'btc-eth-2 owns allpaper10 accounts;research leaves completeplan/state/ledgers and frozenrules unchanged.','registry_after_finish':{'events':len(reg.read_events(ROOT/'research/automation/registry.jsonl')),'IDs':len(records)},'necessary_evidence':'Preserve finishedreport originalbytes andregistrySHA. Keep full9sceneSMA cumulativeNAV/newdailyinputs/4rawresponses;oldsourceledgersnotcopied;8largeParquets remainignoreddata withpath,size,SHA.'};put(R/'next_research_state.json',nxt)
 with (R/'result.md').open('a') as f:f.write('\n补充边界核对：54/54新组合三倍成本收益均低于同BTC参数、同ETH阈值的30日旧组合；新18项通过不能解读为净收益全面改善。完整对照见boundary_comparison.csv。邻接Sharpe描述性陡变筛查标记'+str(len(cliffs))+'条边，阈值'+str(threshold)+'；全部216条边保留，诊断不改已finish门槛/状态。元数据中初始规范试验数按monitor相同观察过滤口径修正为4481，初始含SMA快照的4856保留修正说明；冻结规则和结果字节不变。\n')
 print(json.dumps({'passed':True,'matched_old_comparisons':54,'all54_new_return3_lower_than_matched30':all(r['return3_difference_pp']<0 for r in rows),'csv_metrics_checked':243,'fold_rows_checked':2673,'daily_rows_checked':53622,'adjacent_edges':216,'cliff_edges_flagged':len(cliffs),'finished_report_sha256_unchanged':finished_sha,'qualified_historical_references':len(qualified)},ensure_ascii=False),flush=True)
if __name__=='__main__':main()
